import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // --- AUTH Y NAVEGACIÓN ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [password, setPassword] = useState('');
  const [pantalla, setPantalla] = useState('catalogo');

  // --- DATOS ---
  const [productos, setProductos] = useState([]);
  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  const [fechaHoy] = useState(() => {
    return new Date().toLocaleDateString('es-CO', { 
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
    });
  });

  // --- FORMULARIO ---
  const [nombre, setNombre] = useState('');
  const [categoria, setCategoria] = useState('');
  const [imagenUrl, setImagenUrl] = useState(''); // Estado vacío por defecto para que pongas la tuya
  const [precioCosto, setPrecioCosto] = useState('');
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState('');
  const [stock, setStock] = useState('');

  // --- EFECTOS ---
  useEffect(() => {
    localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia));
  }, [ventasDelDia]);

  useEffect(() => {
    if (isLoggedIn) obtenerInventarioBackend();
  }, [isLoggedIn]);

  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
      }
    } catch (error) {
      console.error("Error al sincronizar con Spring Boot:", error);
    }
  };

  const handleBorrarTodo = async () => {
    if (window.confirm("🚨 ¿ATENCIÓN! ¿Estás seguro de que deseas ELIMINAR TODOS los productos de la base de datos?")) {
      try {
        const respuesta = await fetch('http://localhost:8080/api/productos/vaciar', {
          method: 'DELETE'
        });
        if (respuesta.ok) {
          alert("Base de datos vaciada con éxito.");
          setProductos([]);
          setVentasDelDia([]);
          localStorage.removeItem('ventas_paisita');
        }
      } catch (error) {
        alert("Error de conexión al intentar borrar los datos.");
      }
    }
  };

  const cambiarStockManual = async (producto) => {
    const nuevoStockString = prompt(`Modificar existencias de: ${producto.nombre}\nEscribe el nuevo stock total:`, producto.stock);
    if (nuevoStockString === null) return;

    const nuevoStockNum = parseInt(nuevoStockString, 10);
    if (isNaN(nuevoStockNum) || nuevoStockNum < 0) {
      alert("Número inválido.");
      return;
    }

    const productoActualizado = { ...producto, stock: nuevoStockNum };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(productoActualizado)
      });
      if (respuesta.ok) obtenerInventarioBackend();
    } catch (error) {
      alert("Error al actualizar stock.");
    }
  };

  const handleGuardar = async (e) => {
    e.preventDefault();

    const nuevoProducto = {
      nombre: nombre.trim(),
      categoria,
      imagenUrl: imagenUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c',
      precioCosto: parseFloat(precioCosto),
      impuesto: parseFloat(impuesto),
      precioVenta: parseFloat(precioVenta),
      stock: parseInt(stock)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });

      if (respuesta.ok) {
        alert("¡Producto guardado correctamente!");
        // LIMPIEZA DE FORMULARIO PARA QUE LA SIGUIENTE IMAGEN NO SEA LA ANTERIOR
        setNombre(''); setCategoria(''); setImagenUrl(''); setPrecioCosto(''); setPrecioVenta(''); setStock('');
        obtenerInventarioBackend();
        setPantalla('catalogo');
      } else {
        alert("Error al guardar: Revisa si el nombre está duplicado.");
      }
    } catch (error) {
      alert("Error de conexión con el backend.");
    }
  };

  const registrarVenta = (producto) => {
    if (producto.stock <= 0) {
      alert(`¡Agotado!`);
      return;
    }

    const inventarioActualizado = productos.map((p) => {
      if (p.id === producto.id) return { ...p, stock: p.stock - 1 };
      return p;
    });
    setProductos(inventarioActualizado);

    const costoRealConIva = producto.precioCosto * (1 + producto.impuesto / 100);
    const gananciaNetaGenerada = producto.precioVenta - costoRealConIva;

    const nuevaVenta = {
      id: Date.now(),
      nombre: producto.nombre,
      precioVenta: producto.precioVenta,
      costoConIva: costoRealConIva,
      gananciaNeta: gananciaNetaGenerada,
      hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
    };

    setVentasDelDia([...ventasDelDia, nuevaVenta]);
  };

  const limpiarCierreCaja = () => {
    if (window.confirm("¿Seguro que deseas cerrar la jornada?")) {
      setVentasDelDia([]);
      localStorage.removeItem('ventas_paisita');
    }
  };

  const formatearMoneda = (v) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v || 0);
  const ingresosTotales = ventasDelDia.reduce((sum, v) => sum + v.precioVenta, 0);
  const gananciasTotalesNetas = ventasDelDia.reduce((sum, v) => sum + v.gananciaNeta, 0);

  // --- RENDER LOGIN ---
  if (!isLoggedIn) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', background: '#0f0906', color: '#e3cbb3' }}>
        <div style={{ background: '#1a110d', padding: '40px', borderRadius: '15px', border: '1px solid #3d2b1f', textAlign: 'center' }}>
          <h1>Acceso Paisita UP</h1>
          <input type="password" placeholder="Contraseña" className="form-input" value={password} onChange={(e) => setPassword(e.target.value)} />
          <button className="btn-submit" onClick={() => { if(password === '123') setIsLoggedIn(true); else alert('Clave incorrecta'); }}>Ingresar</button>
        </div>
      </div>
    );
  }

  // --- RENDER APP ---
  return (
    <div className="app-layout">
      <header className="app-header">
        <div className="header-brand">
          <h1>El Paisita UP</h1>
          <p className="fecha-badge">📅 {fechaHoy}</p>
        </div>
        <nav className="header-nav">
          <button className={`nav-link ${pantalla === 'catalogo' ? 'active' : ''}`} onClick={() => setPantalla('catalogo')}>📦 Catálogo</button>
          <button className={`nav-link ${pantalla === 'formulario' ? 'active' : ''}`} onClick={() => setPantalla('formulario')}>➕ Ingresar Mercancía</button>
          <button className={`nav-link-alert ${pantalla === 'reporte' ? 'active' : ''}`} onClick={() => setPantalla('reporte')}>📊 Cierre de Caja ({ventasDelDia.length})</button>
          <button className="btn-nav-clear-database" onClick={handleBorrarTodo}>🔥 Reiniciar Todo</button>
        </nav>
      </header>

      <main className="app-content">
        {pantalla === 'catalogo' && (
          <div className="catalogo-view">
            <div className="grid-catalogo">
              {productos.map((prod) => (
                <div key={prod.id} className="card-producto">
                  <div className="card-image-wrapper">
                    <img src={prod.imagenUrl} alt={prod.nombre} onError={(e)=>{e.target.src="https://images.unsplash.com/photo-1546069901-ba9599a7e63c"}} />
                    <span className="categoria-tag">{prod.categoria}</span>
                  </div>
                  <div className="card-info">
                    <h3>{prod.nombre}</h3>
                    <div className="card-precios">
                      <div><span className="label-precio">P. Venta</span><span className="valor-venta">{formatearMoneda(prod.precioVenta)}</span></div>
                      <div><span className="label-precio">Costo base</span><span className="valor-costo">{formatearMoneda(prod.precioCosto)}</span></div>
                    </div>
                    <p>Existencia: <strong>{prod.stock} uds</strong></p>
                    <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '8px' }}>
                      <button className="btn-vender-card" onClick={() => registrarVenta(prod)} disabled={prod.stock <= 0}>Vender</button>
                      <button className="btn-modificar-stock" onClick={() => cambiarStockManual(prod)}>✏️ Stock</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {pantalla === 'formulario' && (
          <div className="form-container-centered">
            <div className="form-card">
              <h2>Registrar Producto</h2>
              <form onSubmit={handleGuardar}>
                <input type="text" placeholder="Nombre" value={nombre} onChange={(e) => setNombre(e.target.value)} className="form-input" required />
                <input type="text" placeholder="Categoría" value={categoria} onChange={(e) => setCategoria(e.target.value)} className="form-input" required />
                <input type="text" placeholder="URL de la imagen" value={imagenUrl} onChange={(e) => setImagenUrl(e.target.value)} className="form-input" />
                <input type="number" placeholder="Precio Costo" value={precioCosto} onChange={(e) => setPrecioCosto(e.target.value)} className="form-input" required />
                <select value={impuesto} onChange={(e) => setImpuesto(e.target.value)} className="form-input">
                  <option value="19">IVA 19%</option>
                  <option value="8">INC 8%</option>
                  <option value="0">Exento</option>
                </select>
                <input type="number" placeholder="Precio Venta" value={precioVenta} onChange={(e) => setPrecioVenta(e.target.value)} className="form-input" required />
                <input type="number" placeholder="Stock Inicial" value={stock} onChange={(e) => setStock(e.target.value)} className="form-input" required />
                <button type="submit" className="btn-submit">Guardar Producto</button>
              </form>
            </div>
          </div>
        )}

        {pantalla === 'reporte' && (
          <div className="reporte-view">
            <div className="kpi-dashboard">
              <div className="kpi-card"><h3>Ventas</h3><p>{ventasDelDia.length}</p></div>
              <div className="kpi-card"><h3>Recaudo</h3><p>{formatearMoneda(ingresosTotales)}</p></div>
              <div className="kpi-card"><h3>Utilidad</h3><p>{formatearMoneda(gananciasTotalesNetas)}</p></div>
            </div>
            <div className="form-card full-width-card">
              <div className="reporte-header"><h2>Bitácora</h2><button className="btn-clean-caja" onClick={limpiarCierreCaja}>🔒 Cerrar Caja</button></div>
              <table className="tabla-reporte">
                <thead><tr><th>Hora</th><th>Ítem</th><th>Precio</th><th>Ganancia</th></tr></thead>
                <tbody>
                  {ventasDelDia.map((v) => (
                    <tr key={v.id}><td>{v.hora}</td><td>{v.nombre}</td><td>{formatearMoneda(v.precioVenta)}</td><td>{formatearMoneda(v.gananciaNeta)}</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
